code.text:
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.40" }
  }
}
provider "aws" { region = "us-east-1" }
provider "aws" {
  alias  = "eu"
  region = "eu-west-1"
}
resource "aws_s3_bucket" "replica" {
  provider = aws.eu
  bucket   = "acme-replica"
}

data "aws_ami" "base" {
  most_recent = true
  owners      = ["123456789012"]
  filter {
    name   = "name"
    values = ["golden-al2023-*"]
  }
}
resource "aws_instance" "web" {
  ami           = data.aws_ami.base.id
  instance_type = "t3.small"
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "5.8.1"
  name    = "prod"
  cidr    = "10.0.0.0/16"
  azs             = ["us-east-1a", "us-east-1b"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24"]
}
output "vpc_id" { value = module.vpc.vpc_id }

variable "users" { type = set(string) }
resource "aws_iam_user" "u" {
  for_each = var.users
  name     = each.key
}
# removing "bob" destroys only aws_iam_user.u["bob"]

terraform {
  backend "s3" {
    bucket       = "acme-tfstate"
    key          = "prod/network.tfstate"
    region       = "us-east-1"
    encrypt      = true
    use_lockfile = true   # native S3 locking (TF >= 1.10)
  }
}

resource "aws_instance" "web" {
  ami       = data.aws_ami.golden.id   # app pre-baked
  user_data = templatefile("boot.sh.tftpl", { env = var.env })
  # no remote-exec, no SSH from CI
}

resource "aws_instance" "app" {
  ami           = data.aws_ami.app.id
  instance_type = var.instance_type
  lifecycle {
    precondition {
      condition     = data.aws_ami.app.architecture == "x86_64"
      error_message = "AMI must be x86_64 for ${var.instance_type}."
    }
    postcondition {
      condition     = self.public_ip == ""
      error_message = "App instances must not have public IPs."
    }
  }
}
